class FishingChallengeController {
  static const minimumBiteWaitSeconds = 1.5;
  static const maximumBiteWaitSeconds = 3.0;
  static const dangerGraceSeconds = 0.75;
  static const reelRisePerSecond = 0.65;
  static const releaseFallPerSecond = 0.55;
  static const warningProgressMultiplier = 0.25;

  final ValueNotifier<FishingSnapshot> _snapshot = ValueNotifier(
    const FishingSnapshot.inactive(),
  );

  String? _fishItemId;
  FishingChallengeFeature? _feature;
  double _waitSeconds = 0;
  double _phaseElapsedSeconds = 0;
  int _handledReelStartGeneration = 0;

  ValueListenable<FishingSnapshot> get listenable => _snapshot;
  FishingSnapshot get snapshot => _snapshot.value;
  bool get isActive => snapshot.isActive;

  void start({
    required String? fishItemId,
    required FishingChallengeFeature? feature,
    required double waitSeconds,
    required int reelStartGeneration,
  }) {
    if (isActive) {
      throw StateError('Cannot start fishing while another attempt is active.');
    }
    if ((fishItemId == null) != (feature == null)) {
      throw ArgumentError(
        'Fish item ID and challenge feature must either both be set or null.',
      );
    }
    if (!waitSeconds.isFinite || waitSeconds < 0) {
      throw ArgumentError.value(waitSeconds, 'waitSeconds');
    }
    _fishItemId = fishItemId;
    _feature = feature;
    _waitSeconds = waitSeconds;
    _phaseElapsedSeconds = 0;
    _handledReelStartGeneration = reelStartGeneration;
    _snapshot.value = const FishingSnapshot.inactive()._copyWith(
      phase: FishingPhase.waiting,
    );
  }

  FishingResolution? update({
    required double dt,
    required bool reelHeld,
    required int reelStartGeneration,
  }) {
    if (!dt.isFinite || dt < 0) {
      throw ArgumentError.value(dt, 'dt');
    }
    final current = snapshot;
    if (!current.isActive) {
      return null;
    }

    final reelStarted = reelStartGeneration != _handledReelStartGeneration;
    _handledReelStartGeneration = reelStartGeneration;
    switch (current.phase) {
      case FishingPhase.inactive:
        return null;
      case FishingPhase.waiting:
        if (reelStarted) {
          return _resolve(FishingResolutionKind.reeledTooSoon);
        }
        _phaseElapsedSeconds += dt;
        if (_phaseElapsedSeconds < _waitSeconds) {
          return null;
        }
        _phaseElapsedSeconds = 0;
        final feature = _feature;
        if (feature == null) {
          return _resolve(FishingResolutionKind.noBite);
        }
        _snapshot.value = current._copyWith(phase: FishingPhase.bite);
        return null;
      case FishingPhase.bite:
        if (reelStarted && reelHeld) {
          _phaseElapsedSeconds = 0;
          final parameters = _parametersFor(_feature!.difficulty);
          _snapshot.value = current._copyWith(
            phase: FishingPhase.fighting,
            fishItemId: _fishItemId,
            maximumFightSeconds: _feature!.maximumFightSeconds,
            optimalTensionMinimum: parameters.optimalMinimum,
            optimalTensionMaximum: parameters.optimalMaximum,
            dangerTensionMinimum: parameters.dangerMinimum,
            dangerTensionMaximum: parameters.dangerMaximum,
          );
          return null;
        }
        _phaseElapsedSeconds += dt;
        if (_phaseElapsedSeconds >= _feature!.hookWindowSeconds) {
          return _resolve(FishingResolutionKind.missedHook);
        }
        return null;
      case FishingPhase.fighting:
        return _updateFight(dt: dt, reelHeld: reelHeld);
    }
  }

  bool cancel() {
    if (!isActive) {
      return false;
    }
    _reset();
    return true;
  }

  FishingResolution? _updateFight({
    required double dt,
    required bool reelHeld,
  }) {
    final current = snapshot;
    final feature = _feature!;
    final nextElapsed = current.elapsedFightSeconds + dt;
    final struggleForce = _struggleForce(nextElapsed, feature.difficulty);
    final inputForce = reelHeld ? reelRisePerSecond : -releaseFallPerSecond;
    final tension = (current.tension + (inputForce + struggleForce) * dt).clamp(
      0.0,
      1.0,
    );
    final dangerous =
        tension <= current.dangerTensionMinimum ||
        tension >= current.dangerTensionMaximum;
    final dangerSeconds = dangerous ? current.dangerSeconds + dt : 0.0;

    final optimal =
        tension >= current.optimalTensionMinimum &&
        tension <= current.optimalTensionMaximum;
    final progressMultiplier = dangerous
        ? 0.0
        : optimal
        ? 1.0
        : warningProgressMultiplier;
    final minimumSeconds = feature.minimumFightSeconds;
    final landingProgress = math.min(
      1.0,
      current.landingProgress + dt * progressMultiplier / minimumSeconds,
    );
    _snapshot.value = current._copyWith(
      tension: tension,
      landingProgress: landingProgress,
      elapsedFightSeconds: nextElapsed,
      dangerSeconds: dangerSeconds,
      struggleForce: struggleForce,
    );

    if (dangerSeconds >= dangerGraceSeconds) {
      return _resolve(
        tension <= current.dangerTensionMinimum
            ? FishingResolutionKind.lineSlack
            : FishingResolutionKind.lineSnapped,
      );
    }
    if (landingProgress >= 1) {
      return _resolve(FishingResolutionKind.landed);
    }
    if (nextElapsed >= feature.maximumFightSeconds) {
      return _resolve(FishingResolutionKind.exhausted);
    }
    return null;
  }

  FishingResolution _resolve(FishingResolutionKind kind) {
    final resolution = FishingResolution(kind, fishItemId: _fishItemId);
    _reset();
    return resolution;
  }

  void _reset() {
    _fishItemId = null;
    _feature = null;
    _waitSeconds = 0;
    _phaseElapsedSeconds = 0;
    _snapshot.value = const FishingSnapshot.inactive();
  }

  void dispose() => _snapshot.dispose();

  static double waitSecondsForRoll(double roll) {
    if (!roll.isFinite) {
      throw ArgumentError.value(roll, 'roll');
    }
    final normalized = roll.clamp(0.0, 1.0);
    return minimumBiteWaitSeconds +
        (maximumBiteWaitSeconds - minimumBiteWaitSeconds) * normalized;
  }

  static double _struggleForce(
    double elapsedSeconds,
    FishingDifficultyTier difficulty,
  ) => switch (difficulty) {
    FishingDifficultyTier.easy => math.sin(elapsedSeconds * math.pi) * 0.12,
    FishingDifficultyTier.medium =>
      math.sin(elapsedSeconds * math.pi * 2 / 1.35) * 0.22,
    FishingDifficultyTier.hard =>
      math.sin(elapsedSeconds * math.pi * 2 / 1.9) * 0.22 +
          math.sin(elapsedSeconds * math.pi * 2 / 0.8) * 0.10,
  };

  static _FishingTierParameters _parametersFor(
    FishingDifficultyTier difficulty,
  ) => switch (difficulty) {
    FishingDifficultyTier.easy => const _FishingTierParameters(
      optimalMinimum: 0.30,
      optimalMaximum: 0.70,
      dangerMinimum: 0.10,
      dangerMaximum: 0.90,
    ),
    FishingDifficultyTier.medium => const _FishingTierParameters(
      optimalMinimum: 0.35,
      optimalMaximum: 0.65,
      dangerMinimum: 0.15,
      dangerMaximum: 0.85,
    ),
    FishingDifficultyTier.hard => const _FishingTierParameters(
      optimalMinimum: 0.40,
      optimalMaximum: 0.60,
      dangerMinimum: 0.20,
      dangerMaximum: 0.80,
    ),
  };
}

class _FishingTierParameters {
  const _FishingTierParameters({
    required this.optimalMinimum,
    required this.optimalMaximum,
    required this.dangerMinimum,
    required this.dangerMaximum,
  });

  final double optimalMinimum;
  final double optimalMaximum;
  final double dangerMinimum;
  final double dangerMaximum;
}

