    double? struggleForce,
    double? optimalTensionMinimum,
    double? optimalTensionMaximum,
    double? dangerTensionMinimum,

/// authored weight, leaving any probability remainder as a miss.
final class ActivityOutcomeResolver {
  const ActivityOutcomeResolver();

  ActivityOutcomeResult resolve({
    required WorldMap map,
    required String activityId,
    required double x,
    required double y,
    required ActivityRollSource rollSource,
  }) {
    final profiles = <WorldMapActivityProfile>[];
    for (final area in map.activityAreas) {
      if (!area.shape.contains(x, y)) {
        continue;
      }
      for (final profile in area.activities) {
        if (profile.activityId == activityId) {
          profiles.add(profile);
        }
      }
    }
    if (profiles.isEmpty) {
      return const ActivityOutcomeResult.noArea();
    }

    final totalWeight = profiles.fold<double>(
      0,
      (sum, profile) => sum + profile.blendWeight,
    );
    final weightedProbabilities = <String, double>{};
    for (final profile in profiles) {
      for (final outcome in profile.outcomes) {
        weightedProbabilities.update(
          outcome.itemId,
          (value) => value + outcome.probability * profile.blendWeight,
          ifAbsent: () => outcome.probability * profile.blendWeight,
        );
      }
    }

    var threshold = 0.0;
    final roll = rollSource.nextDouble();
    final itemIds = weightedProbabilities.keys.toList()..sort();
    for (final itemId in itemIds) {
      threshold += weightedProbabilities[itemId]! / totalWeight;
      if (roll < threshold) {
        return ActivityOutcomeResult.reward(itemId);
      }
    }
    return const ActivityOutcomeResult.miss();
  }
}

  final VisualElevationProjection projection;

  ItemTileTarget? resolve({
    required Vector2 renderedPoint,
    required Vector2 playerLogicalPosition,
    required RangedTileActivationFeature feature,
  }) {
    if (!renderedPoint.x.isFinite || !renderedPoint.y.isFinite) {
      return null;
    }
    final cellSize = feature.targetCellSize;
    final cellX = (renderedPoint.x / cellSize).floor();
    if (cellX < 0 || cellX * cellSize >= map.width) {
      return null;
    }

    final maximumLevel = map.elevation.cells.fold<int>(
      0,
      (maximum, cell) => cell.level > maximum ? cell.level : maximum,
    );
    final minimumCellY = (renderedPoint.y / cellSize).floor() - 1;
    final maximumCellY =
        ((renderedPoint.y +
                    maximumLevel * VisualElevationProjection.liftPerLevel) /
                cellSize)
            .floor() +
        1;

    ItemTileTarget? frontmost;
    for (var cellY = minimumCellY; cellY <= maximumCellY; cellY++) {
      final logicalTop = cellY * cellSize.toDouble();
      if (cellY < 0 || logicalTop >= map.height) {
        continue;
      }
      final parentX = (cellX * cellSize / map.tileSize).floor();
      final parentY = (cellY * cellSize / map.tileSize).floor();
      final parentLogicalX = parentX * map.tileSize.toDouble();
      final parentLogicalY = parentY * map.tileSize.toDouble();
      final offsetY = projection.visualOffsetYAtCoordinates(
        parentLogicalX,
        parentLogicalY,
      );
      final renderedBounds = Rect.fromLTWH(
        cellX * cellSize.toDouble(),
        logicalTop + offsetY,
        cellSize.toDouble(),
        cellSize.toDouble(),
      );
      if (!renderedBounds.contains(Offset(renderedPoint.x, renderedPoint.y))) {
        continue;
      }

      final logicalCenter = Vector2(
        cellX * cellSize + cellSize / 2,
        logicalTop + cellSize / 2,
      );
      final inRange =
          playerLogicalPosition.distanceTo(logicalCenter) <=
          feature.maximumRange;
      final surfaceMatches = _matchesSurface(
        logicalCenter,
        feature.requiredSurface,
      );
      final validity = !inRange
          ? ItemTargetValidity.outOfRange
          : surfaceMatches
          ? ItemTargetValidity.valid
          : ItemTargetValidity.wrongSurface;
      final candidate = ItemTileTarget(
        cellX: cellX,
        cellY: cellY,
        cellSize: cellSize,
        logicalCenter: logicalCenter,
        renderedBounds: renderedBounds,
        validity: validity,
      );
      if (frontmost == null || candidate.cellY > frontmost.cellY) {
        frontmost = candidate;
      }
    }
    return frontmost;
  }

  bool _matchesSurface(Vector2 logicalCenter, ItemTargetSurface required) {
    if (required == ItemTargetSurface.any) {
      return true;
    }
    for (final layer in map.tileLayers) {
      if (!layer.visible) {
        continue;
      }
      final x = (logicalCenter.x / layer.cellSize).floor();
      final y = (logicalCenter.y / layer.cellSize).floor();
      final paint = layer.effectivePaintAt(x, y);
      final material = switch (paint) {
        CenterMaterialTilePaint(:final material) => material,
        ConnectedMaterialTilePaint(:final material) => material,
        _ => null,
      };
      if (required == ItemTargetSurface.water &&
          material == TileMaterial.water) {
        return true;
      }
    }
    return false;
  }
}

sealed class WorldMapActivityAreaShape {
  const WorldMapActivityAreaShape();

  bool contains(double x, double y);
}

final class WorldMapActivityRectangle extends WorldMapActivityAreaShape {
  const WorldMapActivityRectangle({
    required this.left,
    required this.top,
    required this.width,
    required this.height,
  });

  final double left;
  final double top;
  final double width;
  final double height;

  double get right => left + width;
  double get bottom => top + height;

  @override
  bool contains(double x, double y) =>
      x >= left && x <= right && y >= top && y <= bottom;

  @override
  bool operator ==(Object other) =>
      other is WorldMapActivityRectangle &&
      other.left == left &&
      other.top == top &&
      other.width == width &&
      other.height == height;

  @override
  int get hashCode => Object.hash(left, top, width, height);
}

final class WorldMapActivityPolygon extends WorldMapActivityAreaShape {
  WorldMapActivityPolygon({required List<WorldMapPoint> points})
    : points = List.unmodifiable(points);

  final List<WorldMapPoint> points;

  @override
  bool contains(double x, double y) {
    var inside = false;
    for (
      var index = 0, previous = points.length - 1;
      index < points.length;
      previous = index++
    ) {
      final currentPoint = points[index];
      final previousPoint = points[previous];
      if (_pointOnSegment(x, y, previousPoint, currentPoint)) {
        return true;
      }
      final crosses =
          (currentPoint.y > y) != (previousPoint.y > y) &&
          x <
              (previousPoint.x - currentPoint.x) *
                      (y - currentPoint.y) /
                      (previousPoint.y - currentPoint.y) +
                  currentPoint.x;
      if (crosses) {
        inside = !inside;
      }
    }
    return inside;
  }

  bool _pointOnSegment(
    double x,
    double y,
    WorldMapPoint start,
    WorldMapPoint end,
  ) {
    const epsilon = 0.000001;
    final cross =
        (x - start.x) * (end.y - start.y) - (y - start.y) * (end.x - start.x);
    if (cross.abs() > epsilon) {
      return false;
    }
    return x >= (start.x < end.x ? start.x : end.x) - epsilon &&
        x <= (start.x > end.x ? start.x : end.x) + epsilon &&
        y >= (start.y < end.y ? start.y : end.y) - epsilon &&
        y <= (start.y > end.y ? start.y : end.y) + epsilon;
  }

  @override
  bool operator ==(Object other) =>
      other is WorldMapActivityPolygon && _listEquals(other.points, points);

  @override
  int get hashCode => Object.hashAll(points);
}

