void _resolveFishingOutcome(
  RangedTileActivationFeature feature,
  ItemTileTarget target,
  Vector2 renderedCenter,
) {
  final logicalCenter = target.logicalCenter;
  final outcome = _activityOutcomeResolver.resolve(
    map: mapFor(runtimeState.mapId),
    activityId: feature.activityId,
    x: logicalCenter.x,
    y: logicalCenter.y,
    rollSource: _activityRollSource,
  );
  switch (outcome.kind) {
    case ActivityOutcomeKind.noArea:
      _hudFeedbackController.enqueue(
        const HudFeedback('No fish are biting here.'),
      );
    case ActivityOutcomeKind.miss:
      _startFishingAttempt(
        fishItemId: null,
        challenge: null,
        renderedCenter: renderedCenter,
      );
    case ActivityOutcomeKind.reward:
      final itemId = outcome.itemId!;
      final definition = itemCatalog.findById(itemId);
      final displayLabel = definition?.displayName ?? itemId;
      final challenge = definition?.featureOfType<FishingChallengeFeature>();
      if (challenge == null) {
        _hudFeedbackController.enqueue(
          HudFeedback('Cannot hook $displayLabel.', isError: true),
        );
        return;
      }
      final capacity = _runtimeController.activityRewardCapacity(itemId);
      if (capacity != InventoryAddStatus.added) {
        _enqueueInventoryFailure(capacity, displayLabel);
        return;
      }
      _startFishingAttempt(
        fishItemId: itemId,
        challenge: challenge,
        renderedCenter: renderedCenter,
      );
  }
}

void _startFishingAttempt({
  required String? fishItemId,
  required FishingChallengeFeature? challenge,
  required Vector2 renderedCenter,
}) {
  activeWorld.cancelActiveInteraction();
  input.setMovement(Vector2.zero());
  input.interactEnd();
  _fishingRenderedCenter = renderedCenter.clone();
  _fishingController.start(
    fishItemId: fishItemId,
    feature: challenge,
    waitSeconds: FishingChallengeController.waitSecondsForRoll(
      _activityRollSource.nextDouble(),
    ),
    reelStartGeneration: input.interactionStartGeneration,
  );
}

void _updateFishing(double dt) {
  final previousPhase = fishingSnapshot.phase;
  final resolution = _fishingController.update(
    dt: dt,
    reelHeld: input.isInteractionHeld,
    reelStartGeneration: input.interactionStartGeneration,
  );
  if (previousPhase == FishingPhase.waiting &&
      fishingSnapshot.phase == FishingPhase.bite) {
    final center = _fishingRenderedCenter;
    if (center != null) {
      activeWorld.showFishingCastRipple(center);
    }
  }
  if (resolution == null) {
    return;
  }
  input.interactEnd();
  _fishingRenderedCenter = null;
  _handleFishingResolution(resolution);
}

void _handleFishingResolution(FishingResolution resolution) {
  switch (resolution.kind) {
    case FishingResolutionKind.noBite:
      _hudFeedbackController.enqueue(
        const HudFeedback('Nothing bit this time.'),
      );
    case FishingResolutionKind.reeledTooSoon:
      _hudFeedbackController.enqueue(
        const HudFeedback('Too soon — the fish was scared away.'),
      );
    case FishingResolutionKind.missedHook:
      _hudFeedbackController.enqueue(
        const HudFeedback('Too late — the fish got away.'),
      );
    case FishingResolutionKind.lineSlack:
      _hudFeedbackController.enqueue(
        const HudFeedback('The line went slack. The fish escaped.'),
      );
    case FishingResolutionKind.lineSnapped:
      _hudFeedbackController.enqueue(
        const HudFeedback('The line snapped. The fish escaped.'),
      );
    case FishingResolutionKind.exhausted:
      _hudFeedbackController.enqueue(
        const HudFeedback('The fish fought free.'),
      );
    case FishingResolutionKind.landed:
      final itemId = resolution.fishItemId!;
      final displayLabel =
          itemCatalog.findById(itemId)?.displayName ?? itemId;
      final reward = _runtimeController.addActivityReward(itemId);
      if (!reward.added) {
        _enqueueInventoryFailure(reward.inventoryStatus, displayLabel);
        return;
      }
      _hudFeedbackController.enqueue(HudFeedback('Caught 1 $displayLabel.'));
      requestSave();
  }
}

void _enqueueInventoryFailure(
  InventoryAddStatus status,
  String displayLabel,
) {
  final message = switch (status) {
    InventoryAddStatus.backpackFull => 'Backpack is full.',
    InventoryAddStatus.stackFull => '$displayLabel stack is full.',
    InventoryAddStatus.unknownItem => 'Cannot collect $displayLabel.',
    InventoryAddStatus.added => throw StateError(
      'Successful inventory operation reported as failed.',
    ),
  };
  _hudFeedbackController.enqueue(HudFeedback(message, isError: true));
}

bool cancelFishing({bool showFeedback = true}) {
  if (!_fishingController.cancel()) {
    return false;
  }
  _fishingRenderedCenter = null;
  input.interactEnd();
  if (showFeedback) {
    _hudFeedbackController.enqueue(const HudFeedback('Stopped fishing.'));
  }
  return true;
}

bool cancelItemTargeting() {
  if (!isItemTargetingActive) {
    return false;
  }
  _itemTargeting.value = const ItemTargetingSnapshot.inactive();
  if (_isHydrated && activeWorld.isLoaded) {
    activeWorld.hideItemTargeting();
  }
  mouseCursor = MouseCursor.defer;
  return true;
}

